insert into items (id, skill_id, hub, difficulty, body, options, answer, solution, wrong_option_errors)
values
  ('quadratic-function-vertex--r1', 'quadratic-function-vertex', 'eysh', 1, 'Find the vertex of the parabola $y=(x-3)^2+4$.', '{"A": "$(3,\\,4)$", "B": "$(-3,\\,4)$", "C": "$(3,\\,-4)$", "D": "$(4,\\,3)$"}'::jsonb, 'A', 'In the form $y=(x-h)^2+k$ the vertex is $(h,k)$. Here $h=3$ and $k=4$, so the vertex is $(3,4)$. Check: at $x=3$ the squared term is $0$, which is as small as it can get, and $y=4$.', '{"B": "read $h$ straight off the bracket as $-3$ instead of solving $x-3=0$", "C": "flipped the sign of $k$ as well as the sign inside the bracket", "D": "wrote the coordinates the wrong way round"}'::jsonb),
  ('discrete-random-variable--r3', 'discrete-random-variable', 'eysh', 3, 'A discrete random variable $X$ takes the values $1,2,3$ with $P(X=k)=\dfrac{c}{2^k}$. Find $P(X\ge 2)$.', '{"A": "$\\dfrac{3}{7}$", "B": "$\\dfrac{4}{7}$", "C": "$\\dfrac{3}{8}$", "D": "$\\dfrac{6}{7}$"}'::jsonb, 'A', 'The probabilities must total $1$: $$c\left(\tfrac12+\tfrac14+\tfrac18\right)=c\cdot\tfrac78=1,$$ so $c=\tfrac87$. Then $$P(X\ge 2)=c\left(\tfrac14+\tfrac18\right)=\tfrac87\cdot\tfrac38=\tfrac37.$$', '{"B": "computed $P(X=1)=\\tfrac47$ — the complement of the answer, i.e. read $\\ge$ as $<$", "C": "forgot to find $c$ and added $\\tfrac14+\\tfrac18$ raw", "D": "used $c=\\tfrac87$ but summed all three probabilities instead of the last two"}'::jsonb),
  ('expected-value--r1', 'expected-value', 'eysh', 1, '$X$ takes the value $1$ with probability $\tfrac12$, $2$ with probability $\tfrac{3}{10}$ and $5$ with probability $\tfrac15$. Find $E(X)$.', '{"A": "$\\dfrac{21}{10}$", "B": "$\\dfrac{8}{3}$", "C": "$1$", "D": "$5$"}'::jsonb, 'A', 'Multiply each value by its probability and add: $$E(X)=1\cdot\tfrac12+2\cdot\tfrac{3}{10}+5\cdot\tfrac15=\tfrac12+\tfrac35+1=\tfrac{21}{10}.$$', '{"B": "averaged the three values and ignored the probabilities", "C": "gave the most likely value instead of the mean", "D": "gave the largest value instead of the mean"}'::jsonb),
  ('transformation-matrices--r1', 'transformation-matrices', 'eysh', 1, 'Which matrix represents a reflection in the $x$-axis?', '{"A": "$\\begin{pmatrix}1&0\\\\0&-1\\end{pmatrix}$", "B": "$\\begin{pmatrix}-1&0\\\\0&1\\end{pmatrix}$", "C": "$\\begin{pmatrix}0&1\\\\1&0\\end{pmatrix}$", "D": "$\\begin{pmatrix}-1&0\\\\0&-1\\end{pmatrix}$"}'::jsonb, 'A', 'Reflecting in the $x$-axis keeps $x$ and negates $y$: $(x,y)\mapsto(x,-y)$. The matrix whose columns are the images of $(1,0)$ and $(0,1)$ is therefore $\begin{pmatrix}1&0\\0&-1\end{pmatrix}$. Test it on $(3,5)$: it gives $(3,-5)$.', '{"B": "that is reflection in the $y$-axis — it negates $x$ instead", "C": "that is reflection in the line $y=x$ — it swaps the coordinates", "D": "that is a half-turn about the origin — it negates both coordinates"}'::jsonb),
  ('quartiles-and-iqr--r3', 'quartiles-and-iqr', 'eysh', 3, 'Find the interquartile range of $$4,\;6,\;7,\;9,\;12,\;13,\;15,\;18,\;22.$$', '{"A": "$10$", "B": "$11$", "C": "$18$", "D": "$12$"}'::jsonb, 'A', 'There are nine values, so the median is the fifth, $12$. Exclude it and take the median of each half. Lower half $4,6,7,9$ gives $Q_1=\tfrac{6+7}{2}=6.5$; upper half $13,15,18,22$ gives $Q_3=\tfrac{15+18}{2}=16.5$. Hence $$\text{IQR}=16.5-6.5=10.$$', '{"B": "kept the median $12$ inside both halves, giving $Q_1=7$, $Q_3=18$", "C": "that is the range, $22-4$, not the interquartile range", "D": "gave the median instead of the spread"}'::jsonb),
  ('antiderivative-power--r1', 'antiderivative-power', 'eysh', 1, 'Find $\displaystyle\int 6x^2\,dx$.', '{"A": "$2x^3+C$", "B": "$12x+C$", "C": "$6x^3+C$", "D": "$3x^3+C$"}'::jsonb, 'A', 'Raise the power by one and divide by the new power: $$\int 6x^2\,dx=\frac{6x^{3}}{3}+C=2x^3+C.$$ Check by differentiating: $\frac{d}{dx}(2x^3)=6x^2$.', '{"B": "differentiated instead of integrating", "C": "raised the power but forgot to divide by the new power", "D": "divided by the old power $2$ instead of the new power $3$"}'::jsonb),
  ('antiderivative-power--r3', 'antiderivative-power', 'eysh', 3, '$F$ is an antiderivative of $f(x)=3x^2-4x+1$ and $F(1)=5$. Find $F(2)$.', '{"A": "$7$", "B": "$2$", "C": "$5$", "D": "$8$"}'::jsonb, 'A', 'Integrate first: $F(x)=x^3-2x^2+x+C$. Use the given value to pin $C$: $$F(1)=1-2+1+C=C=5.$$ So $F(x)=x^3-2x^2+x+5$ and $$F(2)=8-8+2+5=7.$$', '{"B": "integrated correctly but dropped the constant, giving $F(2)=2$", "C": "evaluated $f(2)$ instead of $F(2)$", "D": "integrated only the leading term, $3x^2\\to x^3$, and stopped at $2^3$"}'::jsonb),
  ('stationary-points-and-extrema--r1', 'stationary-points-and-extrema', 'eysh', 1, 'Find the $x$-coordinate of the stationary point of $f(x)=x^2-6x+5$.', '{"A": "$3$", "B": "$-3$", "C": "$6$", "D": "$5$"}'::jsonb, 'A', 'A stationary point is where $f''(x)=0$. Here $f''(x)=2x-6$, so $$2x-6=0\quad\Longrightarrow\quad x=3.$$', '{"B": "solved $2x+6=0$ — sign slip on the $-6x$ term", "C": "set the derivative equal to the constant instead of to zero", "D": "quoted the constant term of $f$"}'::jsonb),
  ('graph-transformations--r1', 'graph-transformations', 'eysh', 1, 'The graph of $y=x^2$ is translated $3$ units in the positive $x$-direction. What is the equation of the new graph?', '{"A": "$y=(x-3)^2$", "B": "$y=(x+3)^2$", "C": "$y=x^2-3$", "D": "$y=x^2+3$"}'::jsonb, 'A', 'A horizontal translation of $a$ to the right replaces $x$ by $x-a$, so $y=x^2$ becomes $y=(x-3)^2$. Check where the vertex went: it was at $x=0$, and $(x-3)^2$ is zero at $x=3$ — three units right, as required.', '{"B": "replaced $x$ by $x+3$, which moves the graph three units LEFT", "C": "translated down instead of right", "D": "translated up instead of right"}'::jsonb),
  ('addition-rule--r1', 'addition-rule', 'eysh', 1, '$A$ and $B$ are mutually exclusive with $P(A)=\tfrac25$ and $P(B)=\tfrac12$. Find $P(A\cup B)$.', '{"A": "$\\dfrac{9}{10}$", "B": "$\\dfrac{1}{5}$", "C": "$\\dfrac{1}{10}$", "D": "$\\dfrac{7}{10}$"}'::jsonb, 'A', 'Mutually exclusive means $P(A\cap B)=0$, so the addition rule loses its last term: $$P(A\cup B)=P(A)+P(B)=\tfrac25+\tfrac12=\tfrac{9}{10}.$$', '{"B": "multiplied the probabilities — that is for independent events, and it answers a different question", "C": "subtracted instead of adding", "D": "subtracted a non-zero intersection; for mutually exclusive events there is none"}'::jsonb),
  ('addition-rule--r3', 'addition-rule', 'eysh', 3, '$P(A)=\tfrac35$, $P(B)=\tfrac12$ and $P(A\cup B)=\tfrac45$. Find the probability that exactly one of $A$ and $B$ occurs.', '{"A": "$\\dfrac{1}{2}$", "B": "$\\dfrac{3}{10}$", "C": "$\\dfrac{4}{5}$", "D": "$\\dfrac{1}{5}$"}'::jsonb, 'A', 'First recover the intersection from the addition rule: $$P(A\cap B)=P(A)+P(B)-P(A\cup B)=\tfrac35+\tfrac12-\tfrac45=\tfrac{3}{10}.$$ ''''Exactly one'''' is the union with the overlap removed: $$P(A\cup B)-P(A\cap B)=\tfrac45-\tfrac{3}{10}=\tfrac12.$$', '{"B": "stopped at $P(A\\cap B)$ — that is ''''both'''', not ''''exactly one''''", "C": "gave $P(A\\cup B)$, which counts the overlap as well", "D": "gave the probability that neither occurs"}'::jsonb),
  ('geometric-probability--r1', 'geometric-probability', 'eysh', 1, 'A point is chosen at random on a segment of length $10$ cm. Find the probability that it lies within $3$ cm of the left-hand end.', '{"A": "$\\dfrac{3}{10}$", "B": "$\\dfrac{3}{5}$", "C": "$\\dfrac{1}{3}$", "D": "$\\dfrac{7}{10}$"}'::jsonb, 'A', 'For a uniform choice on a segment the probability is the ratio of lengths: $$P=\frac{3}{10}.$$', '{"B": "counted $3$ cm at BOTH ends, which the question did not ask for", "C": "compared $3$ with the remaining $7$ instead of with the whole $10$", "D": "gave the probability of the complement — further than $3$ cm away"}'::jsonb),
  ('variance-of-random-variable--r1', 'variance-of-random-variable', 'eysh', 1, '$X$ takes the value $0$ or $1$, each with probability $\tfrac12$. Find $\operatorname{Var}(X)$.', '{"A": "$\\dfrac{1}{4}$", "B": "$\\dfrac{1}{2}$", "C": "$\\dfrac{1}{8}$", "D": "$0$"}'::jsonb, 'A', '$E(X)=0\cdot\tfrac12+1\cdot\tfrac12=\tfrac12$ and $E(X^2)=0\cdot\tfrac12+1\cdot\tfrac12=\tfrac12$, so $$\operatorname{Var}(X)=E(X^2)-\bigl(E(X)\bigr)^2=\tfrac12-\tfrac14=\tfrac14.$$', '{"B": "gave $E(X^2)$ and forgot to subtract $\\bigl(E(X)\\bigr)^2$", "C": "halved the variance once too often", "D": "assumed no spread; $X$ does vary, so the variance is not zero"}'::jsonb),
  ('variance-and-sd--r1', 'variance-and-sd', 'eysh', 1, 'Find the variance of the data set $1,\;2,\;3,\;4,\;5$.', '{"A": "$2$", "B": "$10$", "C": "$\\sqrt{2}$", "D": "$\\dfrac{5}{2}$"}'::jsonb, 'A', 'The mean is $\bar x=\tfrac{15}{5}=3$. The squared deviations are $4,1,0,1,4$, which total $10$, so $$\sigma^2=\frac{10}{5}=2.$$', '{"B": "gave the total of the squared deviations without dividing by $5$", "C": "gave the standard deviation $\\sqrt{2}$, not the variance", "D": "divided by $n-1=4$; the population variance divides by $n$"}'::jsonb),
  ('linear-equation-one-variable--r3', 'linear-equation-one-variable', 'eysh', 3, 'Solve $\dfrac{2x-1}{3}-\dfrac{x+2}{4}=\dfrac12$.', '{"A": "$x=\\dfrac{16}{5}$", "B": "$x=2$", "C": "$x=\\dfrac{4}{5}$", "D": "$x=\\dfrac{21}{10}$"}'::jsonb, 'A', 'Multiply every term by $12$: $$4(2x-1)-3(x+2)=6.$$ Expand carefully — the $-3$ multiplies both terms in the bracket: $$8x-4-3x-6=6\quad\Longrightarrow\quad 5x-10=6,$$ so $5x=16$ and $x=\tfrac{16}{5}$.', '{"B": "solved $5x-10=0$, forgetting the right-hand side", "C": "distributed $-3$ over only the first term, getting $8x-4-3x+6=6$", "D": "multiplied only the left-hand side by $12$ and left $\\tfrac12$ alone"}'::jsonb),
  ('remainder-theorem--r1', 'remainder-theorem', 'eysh', 1, 'Find the remainder when $x^3+2x-5$ is divided by $x-1$.', '{"A": "$-2$", "B": "$2$", "C": "$-5$", "D": "$-8$"}'::jsonb, 'A', 'By the remainder theorem the remainder on division by $x-a$ is $f(a)$. Here $a=1$: $$f(1)=1^3+2(1)-5=1+2-5=-2.$$', '{"B": "got the magnitude right but lost the sign", "C": "substituted $x=0$ and read off the constant term", "D": "used $x=-1$; the divisor $x-1$ is zero at $x=+1$"}'::jsonb),
  ('area-between-curves--r1', 'area-between-curves', 'eysh', 1, 'Find the area of the region between $y=x+2$ and $y=x$ for $0\le x\le 3$.', '{"A": "$6$", "B": "$3$", "C": "$12$", "D": "$2$"}'::jsonb, 'A', 'Integrate (upper $-$ lower). The lines are parallel, so the gap is the constant $2$: $$\int_0^3\bigl[(x+2)-x\bigr]dx=\int_0^3 2\,dx=6.$$', '{"B": "integrated the gap over a width of $\\tfrac32$ — halved the interval", "C": "added the two areas under the lines instead of subtracting", "D": "gave the vertical gap between the lines, not the area"}'::jsonb),
  ('monotonicity-from-derivative--r1', 'monotonicity-from-derivative', 'eysh', 1, 'For $f(x)=x^2-4x$, on which interval is $f$ increasing?', '{"A": "$x>2$", "B": "$x<2$", "C": "$x>0$", "D": "$x>4$"}'::jsonb, 'A', '$f''(x)=2x-4$, which is positive exactly when $2x-4>0$, i.e. $x>2$. Check either side of $2$: $f''(1)=-2<0$ and $f''(3)=2>0$.', '{"B": "read the inequality the wrong way — that is where $f$ decreases", "C": "used the root of $f$ rather than the root of $f''$", "D": "solved $2x-4>4$ instead of $2x-4>0$"}'::jsonb),
  ('monotonicity-from-derivative--r3', 'monotonicity-from-derivative', 'eysh', 3, 'For $f(x)=x^3-3x^2-9x+5$, on which interval is $f$ decreasing?', '{"A": "$-1<x<3$", "B": "$-3<x<1$", "C": "$x<-1$ or $x>3$", "D": "$1<x<3$"}'::jsonb, 'A', 'Differentiate and factorise: $$f''(x)=3x^2-6x-9=3(x-3)(x+1).$$ This is negative between its roots, so $f$ decreases on $-1<x<3$. Check the middle: $f''(0)=-9<0$.', '{"B": "factorised to $(x+3)(x-1)$ — the signs inside the brackets are swapped", "C": "gave where $f$ INCREASES, i.e. outside the roots", "D": "used $x=1$ (the vertex of $f''$) as an endpoint instead of the root $x=-1$"}'::jsonb),
  ('tangent-line--r1', 'tangent-line', 'eysh', 1, 'Find the gradient of the tangent to $y=x^2$ at the point where $x=1$.', '{"A": "$2$", "B": "$1$", "C": "$\\dfrac12$", "D": "$4$"}'::jsonb, 'A', 'The gradient of the tangent is the derivative at that point. $\frac{dy}{dx}=2x$, so at $x=1$ the gradient is $2$.', '{"B": "gave the $y$-value $1$ instead of the gradient", "C": "gave the gradient of the NORMAL, $-\\tfrac1{2}$ in size", "D": "substituted $x=2$ rather than $x=1$"}'::jsonb),
  ('composite-functions--r1', 'composite-functions', 'eysh', 1, '$f(x)=2x+1$ and $g(x)=x^2$. Find $(f\circ g)(3)$.', '{"A": "$19$", "B": "$49$", "C": "$13$", "D": "$37$"}'::jsonb, 'A', '$(f\circ g)(3)=f\bigl(g(3)\bigr)$. Work inside out: $g(3)=9$, then $f(9)=2(9)+1=19$.', '{"B": "computed $g\\bigl(f(3)\\bigr)=g(7)=49$ — the functions in the wrong order", "C": "added the two outputs, $f(3)+g(3)-3$, rather than composing", "D": "squared only part of the expression, using $2(3^2)+19$"}'::jsonb),
  ('increasing-decreasing-intervals--r3', 'increasing-decreasing-intervals', 'eysh', 3, 'On which interval is $f(x)=\dfrac{x}{x^2+1}$ increasing?', '{"A": "$-1<x<1$", "B": "$x<-1$ or $x>1$", "C": "$x>0$", "D": "$x>1$"}'::jsonb, 'A', 'By the quotient rule $$f''(x)=\frac{(x^2+1)-x(2x)}{(x^2+1)^2}=\frac{1-x^2}{(x^2+1)^2}.$$ The denominator is always positive, so the sign is the sign of $1-x^2$, which is positive exactly for $-1<x<1$.', '{"B": "gave where $1-x^2<0$ — that is where $f$ decreases", "C": "assumed the function rises for all positive $x$; it turns at $x=1$", "D": "used only the positive root and dropped the interval below $x=-1$"}'::jsonb),
  ('range-of-a-function--r1', 'range-of-a-function', 'eysh', 1, 'Find the range of $f(x)=x^2+3$ for real $x$.', '{"A": "$y\\ge 3$", "B": "$y>3$", "C": "$y\\ge 0$", "D": "$y\\le 3$"}'::jsonb, 'A', '$x^2\ge 0$ for every real $x$, and $x^2=0$ is actually attained at $x=0$. Adding $3$ gives $f(x)\ge 3$, with the value $3$ reached. So the range is $y\ge 3$.', '{"B": "excluded $3$, but $f(0)=3$ so the endpoint IS attained", "C": "gave the range of $x^2$ and forgot to shift it up by $3$", "D": "treated the parabola as opening downwards"}'::jsonb),
  ('range-of-a-function--r3', 'range-of-a-function', 'eysh', 3, 'Find the range of $f(x)=\dfrac{2x+1}{x-3}$.', '{"A": "all real $y$ except $y=2$", "B": "all real $y$ except $y=3$", "C": "all real $y$ except $y=-\\tfrac13$", "D": "all real $y$"}'::jsonb, 'A', 'Rewrite by division: $$\frac{2x+1}{x-3}=2+\frac{7}{x-3}.$$ The fraction $\tfrac{7}{x-3}$ is never zero, so $f(x)$ is never exactly $2$; every other value is reached by choosing $x$ suitably. The range is all reals except $2$.', '{"B": "$3$ is excluded from the DOMAIN, not the range", "C": "that is $f(0)$, a value the function does take", "D": "missed the horizontal asymptote $y=2$, which is never attained"}'::jsonb),
  ('cone--r1', 'cone', 'eysh', 1, 'A cone has base radius $3$ and height $4$. Find its volume.', '{"A": "$12\\pi$", "B": "$36\\pi$", "C": "$16\\pi$", "D": "$4\\pi$"}'::jsonb, 'A', '$$V=\tfrac13\pi r^2h=\tfrac13\pi(3)^2(4)=\tfrac13\pi(36)=12\pi.$$', '{"B": "used the cylinder formula $\\pi r^2h$ and dropped the factor $\\tfrac13$", "C": "swapped the radius and the height", "D": "wrote $\\tfrac13\\pi rh$ — the radius must be squared"}'::jsonb),
  ('inscribed-circumscribed-circles--r1', 'inscribed-circumscribed-circles', 'eysh', 1, 'A circle is circumscribed about a right-angled triangle whose hypotenuse is $10$. Find the radius of that circle.', '{"A": "$5$", "B": "$10$", "C": "$\\dfrac{10}{3}$", "D": "$\\dfrac{5}{2}$"}'::jsonb, 'A', 'By Thales'' theorem the hypotenuse of a right-angled triangle is a diameter of its circumcircle. So $$R=\frac{10}{2}=5.$$', '{"B": "gave the diameter instead of the radius", "C": "used the centroid ratio $\\tfrac13$, which belongs to medians, not to this circle", "D": "halved the hypotenuse twice"}'::jsonb),
  ('line-equation--r3', 'line-equation', 'eysh', 3, 'A line passes through $(2,-1)$ and is perpendicular to $3x-4y=8$. Find its equation.', '{"A": "$4x+3y=5$", "B": "$3x-4y=10$", "C": "$4x-3y=11$", "D": "$3x+4y=2$"}'::jsonb, 'A', 'Rearrange the given line to $y=\tfrac34x-2$, so its gradient is $\tfrac34$. A perpendicular line has gradient $-\tfrac43$, since $\tfrac34\cdot\left(-\tfrac43\right)=-1$. Through $(2,-1)$: $$y+1=-\tfrac43(x-2)\ \Longrightarrow\ 3y+3=-4x+8\ \Longrightarrow\ 4x+3y=5.$$ Every option passes through $(2,-1)$, so the point alone cannot decide it — only the gradient can.', '{"B": "kept the same gradient $\\tfrac34$; that is the PARALLEL line", "C": "took the reciprocal but not the negative, giving gradient $\\tfrac43$", "D": "swapped the coefficients without negating, giving gradient $-\\tfrac34$"}'::jsonb),
  ('pyramid-volume-surface--r1', 'pyramid-volume-surface', 'eysh', 1, 'A pyramid has a square base of side $6$ and height $5$. Find its volume.', '{"A": "$60$", "B": "$180$", "C": "$90$", "D": "$10$"}'::jsonb, 'A', '$$V=\tfrac13\times(\text{base area})\times h=\tfrac13(6^2)(5)=\tfrac13(180)=60.$$', '{"B": "used the prism formula and dropped the factor $\\tfrac13$", "C": "halved instead of taking a third", "D": "used the side $6$ instead of the base area $36$"}'::jsonb),
  ('triangle-medians--r3', 'triangle-medians', 'eysh', 3, 'In triangle $ABC$, $AB=5$, $AC=7$ and $BC=8$. Find the length of the median from $A$.', '{"A": "$\\sqrt{21}$", "B": "$\\sqrt{53}$", "C": "$4$", "D": "$\\dfrac{2\\sqrt{21}}{3}$"}'::jsonb, 'A', 'With $a=BC=8$, $b=CA=7$, $c=AB=5$, the median to side $a$ satisfies $$m_a^2=\frac{2b^2+2c^2-a^2}{4}=\frac{2(49)+2(25)-64}{4}=\frac{98+50-64}{4}=\frac{84}{4}=21,$$ so $m_a=\sqrt{21}$.', '{"B": "added $a^2$ instead of subtracting it", "C": "gave half of $BC$ — that is the distance to the midpoint along the side, not the median", "D": "applied the centroid ratio $\\tfrac23$, which gives the distance from $A$ to the centroid"}'::jsonb),
  ('grouped-frequency-mean--r1', 'grouped-frequency-mean', 'eysh', 1, 'Estimate the mean. Class $0\text{–}10$ has frequency $3$; class $10\text{–}20$ has frequency $2$.', '{"A": "$9$", "B": "$10$", "C": "$14$", "D": "$5$"}'::jsonb, 'A', 'Use the class midpoints, $5$ and $15$, each weighted by its frequency: $$\bar x\approx\frac{3(5)+2(15)}{3+2}=\frac{15+30}{5}=\frac{45}{5}=9.$$', '{"B": "averaged the two midpoints and ignored the frequencies", "C": "used the class upper bounds $10$ and $20$ instead of the midpoints", "D": "used the first class only"}'::jsonb),
  ('algebraic-expressions--r1', 'algebraic-expressions', 'eysh', 1, 'Evaluate $3a-2b$ when $a=4$ and $b=-1$.', '{"A": "$14$", "B": "$10$", "C": "$-14$", "D": "$12$"}'::jsonb, 'A', 'Substitute, and watch the double negative: $$3(4)-2(-1)=12+2=14.$$', '{"B": "read $-2(-1)$ as $-2$, losing the double negative", "C": "right size, wrong sign throughout", "D": "dropped the $-2b$ term entirely"}'::jsonb),
  ('algebraic-expressions--r3', 'algebraic-expressions', 'eysh', 3, 'Simplify $\dfrac{x^2-9}{x^2+x-6}$, where $x\ne 2$ and $x\ne -3$.', '{"A": "$\\dfrac{x-3}{x-2}$", "B": "$\\dfrac{x+3}{x+2}$", "C": "$\\dfrac{x-3}{x+2}$", "D": "$\\dfrac{x+3}{x-2}$"}'::jsonb, 'A', 'Factorise both parts: $$\frac{x^2-9}{x^2+x-6}=\frac{(x-3)(x+3)}{(x+3)(x-2)}.$$ The common factor $x+3$ cancels, leaving $\dfrac{x-3}{x-2}$.', '{"B": "factorised the denominator as $(x+3)(x+2)$ — the product of those is $x^2+5x+6$, not $x^2+x-6$", "C": "cancelled $x+3$ from the top but $x-2$ from the bottom incorrectly, keeping $+2$", "D": "cancelled the wrong factor, keeping $x+3$ instead of $x-3$"}'::jsonb),
  ('binomial-theorem--r1', 'binomial-theorem', 'eysh', 1, 'In the expansion of $(x+2)^3$, find the coefficient of $x^2$.', '{"A": "$6$", "B": "$3$", "C": "$12$", "D": "$2$"}'::jsonb, 'A', 'The term in $x^2$ is $\binom{3}{1}x^2(2)^1=3\cdot 2\,x^2=6x^2$, so the coefficient is $6$.', '{"B": "gave $\\binom{3}{1}$ and forgot to multiply by the $2$", "C": "gave the coefficient of $x$, which is $12$", "D": "gave the $2$ from the bracket without the binomial coefficient"}'::jsonb),
  ('polynomial-arithmetic--r1', 'polynomial-arithmetic', 'eysh', 1, 'Simplify $(2x^2+3x-1)+(x^2-5x+4)$.', '{"A": "$3x^2-2x+3$", "B": "$3x^2+8x+3$", "C": "$3x^2-2x-5$", "D": "$2x^2-2x+3$"}'::jsonb, 'A', 'Collect like terms: $2x^2+x^2=3x^2$, $3x-5x=-2x$, $-1+4=3$. So the sum is $3x^2-2x+3$.', '{"B": "subtracted the second bracket instead of adding, then mishandled the signs", "C": "took $-1-4$ for the constant instead of $-1+4$", "D": "forgot to add the $x^2$ terms together"}'::jsonb),
  ('quadratic-formula--r3', 'quadratic-formula', 'eysh', 3, 'Solve $2x^2-4x-3=0$.', '{"A": "$x=\\dfrac{2\\pm\\sqrt{10}}{2}$", "B": "$x=\\dfrac{2\\pm\\sqrt{10}}{4}$", "C": "$x=\\dfrac{-2\\pm\\sqrt{10}}{2}$", "D": "$x=\\dfrac{4\\pm\\sqrt{10}}{4}$"}'::jsonb, 'A', 'Here $a=2$, $b=-4$, $c=-3$, so the discriminant is $(-4)^2-4(2)(-3)=16+24=40$ and $$x=\frac{4\pm\sqrt{40}}{4}=\frac{4\pm 2\sqrt{10}}{4}=\frac{2\pm\sqrt{10}}{2}.$$ The last step matters: every term of the numerator must be halved, not just one of them.', '{"B": "cancelled the $2$ from $4\\pm 2\\sqrt{10}$ but not from the denominator", "C": "used $-b=-4$ instead of $-b=+4$", "D": "cancelled the $2$ inside the surd only, leaving the $4$ untouched"}'::jsonb),
  ('complementary-events--r3', 'complementary-events', 'eysh', 3, 'A bag holds $5$ red and $3$ blue counters. Two are drawn without replacement. Find the probability that at least one is red.', '{"A": "$\\dfrac{25}{28}$", "B": "$\\dfrac{3}{28}$", "C": "$\\dfrac{5}{8}$", "D": "$\\dfrac{15}{28}$"}'::jsonb, 'A', '''''At least one red'''' is easier through its complement, ''''both blue'''': $$P(\text{both blue})=\frac38\cdot\frac27=\frac{3}{28}.$$ Therefore $$P(\text{at least one red})=1-\frac{3}{28}=\frac{25}{28}.$$', '{"B": "gave the complement itself — the probability that NO counter is red", "C": "gave the chance the FIRST counter is red, ignoring the second draw", "D": "counted exactly one red and left out the case of two reds"}'::jsonb),
  ('definite-integral-absolute--r1', 'definite-integral-absolute', 'eysh', 1, 'Evaluate $\displaystyle\int_{-2}^{2}|x|\,dx$.', '{"A": "$4$", "B": "$0$", "C": "$2$", "D": "$8$"}'::jsonb, 'A', '$|x|$ is symmetric about the $y$-axis, so split at $0$ and double one half: $$\int_{-2}^{2}|x|\,dx=2\int_0^2 x\,dx=2\left[\tfrac{x^2}{2}\right]_0^2=2(2)=4.$$ Geometrically this is two triangles of area $2$ each.', '{"B": "integrated $x$ rather than $|x|$; $x$ is odd so it cancels, but $|x|$ never goes below the axis", "C": "found only the right-hand half", "D": "doubled the answer once too often"}'::jsonb),
  ('derivative-exp-log--r1', 'derivative-exp-log', 'eysh', 1, 'Differentiate $y=e^{2x}$.', '{"A": "$2e^{2x}$", "B": "$e^{2x}$", "C": "$2e^{x}$", "D": "$\\dfrac{e^{2x}}{2}$"}'::jsonb, 'A', 'By the chain rule, $\frac{d}{dx}e^{u}=e^{u}\frac{du}{dx}$ with $u=2x$, so $$\frac{dy}{dx}=e^{2x}\cdot 2=2e^{2x}.$$', '{"B": "forgot the chain-rule factor from the inner function $2x$", "C": "differentiated the exponent as well as bringing it down", "D": "integrated instead of differentiating"}'::jsonb),
  ('derivative-exp-log--r3', 'derivative-exp-log', 'eysh', 3, 'Differentiate $y=x^2\ln x$ for $x>0$.', '{"A": "$2x\\ln x+x$", "B": "$2x\\ln x$", "C": "$2x\\ln x+x^2$", "D": "$2x+\\dfrac{1}{x}$"}'::jsonb, 'A', 'Product rule with $u=x^2$ and $v=\ln x$: $$\frac{dy}{dx}=2x\ln x+x^2\cdot\frac1x=2x\ln x+x.$$', '{"B": "differentiated only the first factor", "C": "used $\\frac{d}{dx}\\ln x=1$ instead of $\\tfrac1x$", "D": "differentiated the two factors separately and added, instead of using the product rule"}'::jsonb),
  ('derivative-trig--r3', 'derivative-trig', 'eysh', 3, 'Differentiate $y=\tan(x^2)$.', '{"A": "$2x\\sec^2(x^2)$", "B": "$\\sec^2(x^2)$", "C": "$2x\\tan(x^2)$", "D": "$2x\\sec^2(2x)$"}'::jsonb, 'A', 'Chain rule with $u=x^2$: $\frac{d}{dx}\tan u=\sec^2 u\cdot\frac{du}{dx}$, so $$\frac{dy}{dx}=\sec^2(x^2)\cdot 2x=2x\sec^2(x^2).$$', '{"B": "forgot the inner derivative $2x$", "C": "kept $\\tan$ instead of differentiating it to $\\sec^2$", "D": "differentiated the inner function inside the $\\sec^2$ as well as outside"}'::jsonb),
  ('higher-order-derivatives--r1', 'higher-order-derivatives', 'eysh', 1, 'For $f(x)=x^4$, find $f''''(x)$.', '{"A": "$12x^2$", "B": "$4x^3$", "C": "$24x$", "D": "$12x^3$"}'::jsonb, 'A', 'Differentiate twice: $f''(x)=4x^3$, then $f''''(x)=12x^2$.', '{"B": "stopped after one differentiation", "C": "differentiated three times", "D": "reduced the coefficient but not the power"}'::jsonb),
  ('higher-order-derivatives--r3', 'higher-order-derivatives', 'eysh', 3, 'For $f(x)=\dfrac{x}{x+1}$, find $f''''(1)$.', '{"A": "$-\\dfrac14$", "B": "$\\dfrac14$", "C": "$-\\dfrac12$", "D": "$-2$"}'::jsonb, 'A', 'Quotient rule gives $$f''(x)=\frac{(x+1)-x}{(x+1)^2}=\frac{1}{(x+1)^2}=(x+1)^{-2},$$ so $$f''''(x)=-2(x+1)^{-3}=\frac{-2}{(x+1)^3}.$$ At $x=1$: $f''''(1)=\frac{-2}{8}=-\tfrac14$.', '{"B": "gave $f''(1)$ instead of $f''''(1)$", "C": "used $(x+1)^2=4$ in the denominator rather than $(x+1)^3=8$", "D": "stopped at the numerator $-2$ and never substituted"}'::jsonb),
  ('integration-by-substitution--r1', 'integration-by-substitution', 'eysh', 1, 'Find $\displaystyle\int 2x\,(x^2+5)^3\,dx$.', '{"A": "$\\dfrac{(x^2+5)^4}{4}+C$", "B": "$(x^2+5)^4+C$", "C": "$\\dfrac{(x^2+5)^4}{8}+C$", "D": "$\\dfrac{2x(x^2+5)^4}{4}+C$"}'::jsonb, 'A', 'Let $u=x^2+5$, so $du=2x\,dx$ — the $2x$ in front is exactly what the substitution needs. Then $$\int u^3\,du=\frac{u^4}{4}+C=\frac{(x^2+5)^4}{4}+C.$$ Check by differentiating: $\frac{d}{dx}\frac{(x^2+5)^4}{4}=2x(x^2+5)^3$.', '{"B": "raised the power but never divided by the new power", "C": "divided by $8$, double-counting the $2$ that $du$ had already absorbed", "D": "kept the $2x$ after substituting, so it is counted twice"}'::jsonb),
  ('normal-line--r1', 'normal-line', 'eysh', 1, 'Find the gradient of the normal to $y=x^2$ at the point where $x=1$.', '{"A": "$-\\dfrac12$", "B": "$2$", "C": "$\\dfrac12$", "D": "$-2$"}'::jsonb, 'A', 'The tangent gradient is $\frac{dy}{dx}=2x=2$ at $x=1$. The normal is perpendicular to it, so its gradient is the negative reciprocal: $$m_{\text{normal}}=-\frac{1}{2}.$$', '{"B": "gave the tangent gradient, not the normal", "C": "took the reciprocal but forgot the negative", "D": "negated the tangent gradient instead of taking the negative reciprocal"}'::jsonb),
  ('normal-line--r3', 'normal-line', 'eysh', 3, 'Find the equation of the normal to $y=x^3-2x$ at the point where $x=1$.', '{"A": "$y=-x$", "B": "$y=x-2$", "C": "$y=-\\dfrac{x}{3}-\\dfrac23$", "D": "$y=x$"}'::jsonb, 'A', 'At $x=1$ the point is $(1,-1)$. The derivative is $y''=3x^2-2$, so the tangent gradient is $3-2=1$ and the normal gradient is $-1$. Then $$y-(-1)=-1(x-1)\ \Longrightarrow\ y+1=-x+1\ \Longrightarrow\ y=-x.$$', '{"B": "used the tangent gradient $1$ instead of the normal gradient $-1$", "C": "used $-\\tfrac{1}{3x^2}$, forgetting the $-2$ in $y''$", "D": "got the gradient sign right but lost the point, drawing the line through the origin with gradient $1$"}'::jsonb),
  ('rational-function-asymptotes--r1', 'rational-function-asymptotes', 'eysh', 1, 'Find the vertical asymptote of $y=\dfrac{1}{x-4}$.', '{"A": "$x=4$", "B": "$x=-4$", "C": "$y=4$", "D": "$x=0$"}'::jsonb, 'A', 'A vertical asymptote sits where the denominator is zero and the numerator is not: $x-4=0$, so $x=4$.', '{"B": "solved $x+4=0$ — sign slip", "C": "named a horizontal line; the asymptote here is vertical", "D": "gave the $y$-axis, which is where $x$ itself is zero"}'::jsonb),
  ('rational-function-asymptotes--r3', 'rational-function-asymptotes', 'eysh', 3, 'Find the horizontal asymptote of $y=\dfrac{2x^2-x}{3x^2+5}$.', '{"A": "$y=\\dfrac23$", "B": "$y=0$", "C": "$y=2$", "D": "there is no horizontal asymptote"}'::jsonb, 'A', 'Numerator and denominator have the same degree, so divide through by $x^2$: $$\frac{2-\tfrac1x}{3+\tfrac{5}{x^2}}\longrightarrow\frac{2}{3}\quad\text{as }x\to\pm\infty.$$ The horizontal asymptote is $y=\tfrac23$.', '{"B": "that is the rule when the denominator has the HIGHER degree; here the degrees match", "C": "used the numerator''s leading coefficient alone", "D": "that is the case when the NUMERATOR has the higher degree"}'::jsonb),
  ('coordinate-distance--r3', 'coordinate-distance', 'eysh', 3, 'The point $(a,3)$ is $5$ units from $(1,-1)$. Find the possible values of $a$.', '{"A": "$a=4$ or $a=-2$", "B": "$a=4$ only", "C": "$a=2$ or $a=-4$", "D": "$a=6$ or $a=-4$"}'::jsonb, 'A', 'Square the distance formula: $$(a-1)^2+(3-(-1))^2=5^2\ \Longrightarrow\ (a-1)^2+16=25,$$ so $(a-1)^2=9$ and $a-1=\pm 3$. Hence $a=4$ or $a=-2$.', '{"B": "took only the positive square root; $(a-1)^2=9$ has two solutions", "C": "solved $a=\\pm3-1$ instead of $a=1\\pm3$", "D": "used $(3-(-1))^2=9$, mis-subtracting the negative $y$-coordinate"}'::jsonb),
  ('cylinder--r1', 'cylinder', 'eysh', 1, 'A cylinder has radius $2$ and height $5$. Find its volume.', '{"A": "$20\\pi$", "B": "$80\\pi$", "C": "$10\\pi$", "D": "$40\\pi$"}'::jsonb, 'A', '$$V=\pi r^2h=\pi(2)^2(5)=20\pi.$$', '{"B": "used the diameter $4$ as the radius", "C": "forgot to square the radius", "D": "used $2\\pi r^2h$, borrowing the $2$ from the surface-area formula"}'::jsonb),
  ('cylinder--r3', 'cylinder', 'eysh', 3, 'A cylinder has volume $54\pi$ and height $6$. Find its total surface area.', '{"A": "$54\\pi$", "B": "$36\\pi$", "C": "$45\\pi$", "D": "$90\\pi$"}'::jsonb, 'A', 'First recover the radius from the volume: $\pi r^2(6)=54\pi$ gives $r^2=9$, so $r=3$. Then $$A=2\pi r^2+2\pi rh=2\pi(9)+2\pi(3)(6)=18\pi+36\pi=54\pi.$$ That the answer equals the volume numerically is a coincidence of these numbers, not a rule.', '{"B": "gave the curved surface only, leaving out both circular ends", "C": "counted only one circular end", "D": "used the height $6$ as the radius in the curved-surface term"}'::jsonb),
  ('homothety--r1', 'homothety', 'eysh', 1, 'An enlargement with centre the origin and scale factor $3$ maps $A(2,-1)$ to $A''$. Find $A''$.', '{"A": "$(6,-3)$", "B": "$(5,2)$", "C": "$\\left(\\tfrac23,-\\tfrac13\\right)$", "D": "$(-6,3)$"}'::jsonb, 'A', 'An enlargement about the origin multiplies both coordinates by the scale factor: $$A''=(3\times 2,\;3\times(-1))=(6,-3).$$', '{"B": "added $3$ to each coordinate — that is a translation, not an enlargement", "C": "divided by the scale factor instead of multiplying", "D": "used scale factor $-3$"}'::jsonb),
  ('reflection--r1', 'reflection', 'eysh', 1, 'Reflect the point $(3,-2)$ in the $x$-axis.', '{"A": "$(3,2)$", "B": "$(-3,-2)$", "C": "$(-3,2)$", "D": "$(-2,3)$"}'::jsonb, 'A', 'Reflection in the $x$-axis fixes $x$ and negates $y$: $(x,y)\mapsto(x,-y)$, so $(3,-2)\mapsto(3,2)$.', '{"B": "reflected in the $y$-axis instead", "C": "reflected through the origin — both coordinates negated", "D": "reflected in the line $y=x$ — the coordinates swapped"}'::jsonb),
  ('space-geometry-angles--r3', 'space-geometry-angles', 'eysh', 3, 'In a cube, find the cosine of the angle between a space diagonal and an edge that meets it.', '{"A": "$\\dfrac{\\sqrt3}{3}$", "B": "$\\dfrac{\\sqrt2}{2}$", "C": "$\\dfrac13$", "D": "$\\dfrac{\\sqrt6}{3}$"}'::jsonb, 'A', 'Put the cube on the axes with edge $1$. The space diagonal is $\mathbf{d}=(1,1,1)$ and the edge is $\mathbf{e}=(1,0,0)$. Then $$\cos\theta=\frac{\mathbf{d}\cdot\mathbf{e}}{|\mathbf{d}||\mathbf{e}|}=\frac{1}{\sqrt3\cdot 1}=\frac{\sqrt3}{3}.$$', '{"B": "used the FACE diagonal $(1,1,0)$ instead of the space diagonal", "C": "divided by $3$ rather than by $\\sqrt3$", "D": "used $\\sqrt2$ in the numerator, as though the dot product were $\\sqrt2$"}'::jsonb),
  ('translation--r3', 'translation', 'eysh', 3, 'A translation maps $(2,-1)$ to $(-1,3)$. Find the image of $(5,4)$ under the same translation.', '{"A": "$(2,8)$", "B": "$(8,0)$", "C": "$(9,1)$", "D": "$(4,7)$"}'::jsonb, 'A', 'Find the translation vector first: $$\mathbf{t}=(-1-2,\;3-(-1))=(-3,4).$$ Apply the same vector to $(5,4)$: $$(5-3,\;4+4)=(2,8).$$', '{"B": "applied the translation backwards, $(5+3,\\;4-4)$", "C": "swapped the components of $\\mathbf{t}$", "D": "used the image point $(-1,3)$ as the translation vector"}'::jsonb),
  ('triangle-altitude--r1', 'triangle-altitude', 'eysh', 1, 'A right-angled triangle has legs $6$ and $8$. Find the length of the altitude to the hypotenuse.', '{"A": "$\\dfrac{24}{5}$", "B": "$5$", "C": "$7$", "D": "$\\dfrac{10}{3}$"}'::jsonb, 'A', 'The hypotenuse is $\sqrt{6^2+8^2}=10$. Computing the area two ways, $$\tfrac12(6)(8)=\tfrac12(10)h\ \Longrightarrow\ h=\frac{48}{10}=\frac{24}{5}.$$', '{"B": "gave half the hypotenuse — that is the median to the hypotenuse, not the altitude", "C": "averaged the two legs", "D": "divided the hypotenuse by $3$"}'::jsonb),
  ('combined-standard-deviation--r1', 'combined-standard-deviation', 'eysh', 1, 'One group of $3$ values has mean $4$; another group of $2$ values has mean $9$. Find the mean of all $5$ values.', '{"A": "$6$", "B": "$\\dfrac{13}{2}$", "C": "$30$", "D": "$\\dfrac{13}{5}$"}'::jsonb, 'A', 'Recover each group''s total, then divide by the combined count: $$\bar x=\frac{3(4)+2(9)}{3+2}=\frac{12+18}{5}=\frac{30}{5}=6.$$', '{"B": "averaged the two means, which ignores that the groups differ in size", "C": "gave the combined total without dividing", "D": "divided the sum of the means by the number of values"}'::jsonb),
  ('cumulative-frequency--r1', 'cumulative-frequency', 'eysh', 1, 'A cumulative frequency table shows $4$ values are $\le 10$ and $11$ values are $\le 20$. How many values lie in $10<x\le 20$?', '{"A": "$7$", "B": "$11$", "C": "$15$", "D": "$4$"}'::jsonb, 'A', 'A cumulative figure counts everything up to that point, so the class frequency is the difference: $$11-4=7.$$', '{"B": "read the cumulative total as though it were the class frequency", "C": "added the two cumulative figures", "D": "gave the count for the first class instead"}'::jsonb),
  ('cumulative-frequency--r2', 'cumulative-frequency', 'eysh', 2, 'A cumulative frequency table for $40$ values gives $14$ values $\le 30$ and $23$ values $\le 40$. Which class contains the median?', '{"A": "$30<x\\le 40$", "B": "$20<x\\le 30$", "C": "$40<x\\le 50$", "D": "$10<x\\le 20$"}'::jsonb, 'A', 'With $40$ values the median sits at position $\tfrac{40}{2}=20$. Only $14$ values reach $30$, and $23$ reach $40$, so the $20$th value lies between them: the class $30<x\le 40$.', '{"B": "stopped at the class whose cumulative frequency is $14$, before reaching position $20$", "C": "went one class too far", "D": "used the frequency $14$ as a position rather than a count"}'::jsonb),
  ('factor-theorem--r1', 'factor-theorem', 'eysh', 1, 'Which of these is a factor of $f(x)=x^3-2x^2-5x+6$?', '{"A": "$x-1$", "B": "$x+1$", "C": "$x-2$", "D": "$x+3$"}'::jsonb, 'A', 'By the factor theorem, $x-a$ is a factor exactly when $f(a)=0$. Testing: $$f(1)=1-2-5+6=0,$$ so $x-1$ is a factor. The others give $f(-1)=8$, $f(2)=-4$ and $f(-3)=-24$, none of them zero.', '{"B": "$f(-1)=8\\ne 0$ — the sign of the root was flipped", "C": "$f(2)=-4\\ne 0$", "D": "$f(-3)=-24\\ne 0$"}'::jsonb),
  ('factor-theorem--r3', 'factor-theorem', 'eysh', 3, 'Factorise $x^3-2x^2-5x+6$ completely.', '{"A": "$(x-1)(x-3)(x+2)$", "B": "$(x-1)(x+3)(x-2)$", "C": "$(x+1)(x-3)(x+2)$", "D": "$(x-1)(x-3)(x-2)$"}'::jsonb, 'A', '$f(1)=0$, so $x-1$ is a factor. Dividing gives $$x^3-2x^2-5x+6=(x-1)(x^2-x-6)=(x-1)(x-3)(x+2).$$ Check the constant term: $(-1)(-3)(2)=6$. ✓', '{"B": "factorised the quadratic as $(x+3)(x-2)$, whose product is $x^2+x-6$, not $x^2-x-6$", "C": "used the root $-1$; $f(-1)=8$, so $x+1$ is not a factor", "D": "all three signs negative gives a constant term of $-6$, not $+6$"}'::jsonb),
  ('factoring-cubes--r1', 'factoring-cubes', 'eysh', 1, 'Factorise $x^3-8$.', '{"A": "$(x-2)(x^2+2x+4)$", "B": "$(x-2)(x^2-2x+4)$", "C": "$(x-2)(x^2+4x+4)$", "D": "$(x+2)(x^2-2x+4)$"}'::jsonb, 'A', 'Using $a^3-b^3=(a-b)(a^2+ab+b^2)$ with $a=x$, $b=2$: $$x^3-8=(x-2)(x^2+2x+4).$$ Note the middle sign inside the quadratic is PLUS even though the first bracket has a minus.', '{"B": "made the middle term negative; the quadratic factor of a DIFFERENCE of cubes has $+ab$", "C": "used $(x+2)^2$ for the quadratic factor", "D": "that factorises $x^3+8$, the SUM of cubes"}'::jsonb),
  ('radical-equations--r3', 'radical-equations', 'eysh', 3, 'Solve $\sqrt{x+7}=x-5$.', '{"A": "$x=9$ only", "B": "$x=2$ or $x=9$", "C": "$x=2$ only", "D": "no real solution"}'::jsonb, 'A', 'Square both sides: $x+7=x^2-10x+25$, so $x^2-11x+18=0$ and $(x-2)(x-9)=0$. Squaring can create solutions the original equation never had, so test both. At $x=2$: $\sqrt9=3$ but $x-5=-3$ — a square root is never negative, so $x=2$ fails. At $x=9$: $\sqrt{16}=4=9-5$. ✓ Only $x=9$ works.', '{"B": "solved the quadratic but never checked back in the original equation", "C": "kept the extraneous root and discarded the genuine one", "D": "rejected both roots; $x=9$ does satisfy the equation"}'::jsonb),
  ('rate-and-work-problems--r1', 'rate-and-work-problems', 'eysh', 1, 'A car travels $150$ km in $2$ hours. Find its average speed.', '{"A": "$75$ km/h", "B": "$300$ km/h", "C": "$150$ km/h", "D": "$37.5$ km/h"}'::jsonb, 'A', '$$\text{speed}=\frac{\text{distance}}{\text{time}}=\frac{150}{2}=75\text{ km/h}.$$', '{"B": "multiplied distance by time instead of dividing", "C": "gave the distance rather than the speed", "D": "divided by $4$ instead of $2$"}'::jsonb),
  ('rate-and-work-problems--r3', 'rate-and-work-problems', 'eysh', 3, 'One tap fills a tank in $6$ hours and another fills it in $3$ hours. How long do they take together?', '{"A": "$2$ hours", "B": "$4.5$ hours", "C": "$9$ hours", "D": "$\\dfrac12$ hour"}'::jsonb, 'A', 'Add the RATES, not the times. In one hour the taps fill $\tfrac16$ and $\tfrac13$ of the tank, so together $$\tfrac16+\tfrac13=\tfrac12\ \text{of the tank per hour},$$ and the whole tank takes $1\div\tfrac12=2$ hours.', '{"B": "averaged the two times; two taps must be faster than the faster one alone", "C": "added the two times", "D": "gave the combined rate $\\tfrac12$ instead of inverting it to get the time"}'::jsonb),
  ('systems-nonlinear--r1', 'systems-nonlinear', 'eysh', 1, 'Solve the system $y=x^2$, $y=4$.', '{"A": "$x=2$ or $x=-2$", "B": "$x=2$ only", "C": "$x=16$", "D": "$x=4$ or $x=-4$"}'::jsonb, 'A', 'Substitute: $x^2=4$, so $x=\pm 2$. Both give $y=4$, so there are two intersection points, $(2,4)$ and $(-2,4)$.', '{"B": "took only the positive square root", "C": "squared $4$ instead of square-rooting it", "D": "used $y$ itself as the $x$-value"}'::jsonb),
  ('systems-nonlinear--r3', 'systems-nonlinear', 'eysh', 3, 'Solve $x+y=5$ and $x^2+y^2=13$.', '{"A": "$(2,3)$ and $(3,2)$", "B": "$(1,4)$ and $(4,1)$", "C": "$(2,3)$ only", "D": "no real solution"}'::jsonb, 'A', 'Square the first equation: $x^2+2xy+y^2=25$. Subtracting $x^2+y^2=13$ gives $2xy=12$, so $xy=6$. Now $x$ and $y$ are the roots of $$t^2-5t+6=0\ \Longrightarrow\ (t-2)(t-3)=0,$$ so the solutions are $(2,3)$ and $(3,2)$.', '{"B": "$1+4=5$ but $1^2+4^2=17$, not $13$", "C": "the system is symmetric in $x$ and $y$, so the swapped pair is a solution too", "D": "the line does meet the circle — twice"}'::jsonb),
  ('dot-product--r1', 'dot-product', 'eysh', 1, '$\mathbf{a}=(3,4)$ and $\mathbf{b}=(1,2)$. Find $\mathbf{a}\cdot\mathbf{b}$.', '{"A": "$11$", "B": "$-5$", "C": "$5$", "D": "$7$"}'::jsonb, 'A', 'Multiply matching components and add: $$\mathbf{a}\cdot\mathbf{b}=3(1)+4(2)=3+8=11.$$', '{"B": "subtracted the second product instead of adding", "C": "gave $|\\mathbf{a}|$ rather than the scalar product", "D": "added the components of $\\mathbf{a}$ and ignored $\\mathbf{b}$"}'::jsonb),
  ('dot-product--r3', 'dot-product', 'eysh', 3, 'Find $k$ so that $(2,k)$ and $(3,-6)$ are perpendicular.', '{"A": "$k=1$", "B": "$k=-1$", "C": "$k=4$", "D": "$k=-4$"}'::jsonb, 'A', 'Perpendicular vectors have zero scalar product: $$2(3)+k(-6)=0\ \Longrightarrow\ 6-6k=0\ \Longrightarrow\ k=1.$$', '{"B": "solved $6+6k=0$ — the $-6$ was dropped", "C": "set the scalar product equal to the first component rather than to zero", "D": "solved for parallel vectors instead of perpendicular ones"}'::jsonb),
  ('inverse-matrix-2x2--r1', 'inverse-matrix-2x2', 'eysh', 1, 'Find the inverse of $\begin{pmatrix}3&1\\5&2\end{pmatrix}$.', '{"A": "$\\begin{pmatrix}2&-1\\\\-5&3\\end{pmatrix}$", "B": "$\\begin{pmatrix}2&1\\\\5&3\\end{pmatrix}$", "C": "$\\begin{pmatrix}3&-1\\\\-5&2\\end{pmatrix}$", "D": "$\\begin{pmatrix}2&-5\\\\-1&3\\end{pmatrix}$"}'::jsonb, 'A', 'The determinant is $3(2)-1(5)=1$. For a $2\times2$ matrix, $$\begin{pmatrix}a&b\\c&d\end{pmatrix}^{-1}=\frac{1}{ad-bc}\begin{pmatrix}d&-b\\-c&a\end{pmatrix}:$$ swap the leading diagonal, negate the other two, divide by the determinant. Here that gives $\begin{pmatrix}2&-1\\-5&3\end{pmatrix}$.', '{"B": "swapped the diagonal but forgot to negate the off-diagonal entries", "C": "negated the off-diagonal but forgot to swap the leading diagonal", "D": "transposed the matrix instead of applying the inverse formula"}'::jsonb),
  ('vectors-in-polygons--r1', 'vectors-in-polygons', 'eysh', 1, '$ABCD$ is a parallelogram with $\vec{AB}=\mathbf{a}$ and $\vec{AD}=\mathbf{b}$. Express $\vec{AC}$ in terms of $\mathbf{a}$ and $\mathbf{b}$.', '{"A": "$\\mathbf{a}+\\mathbf{b}$", "B": "$\\mathbf{a}-\\mathbf{b}$", "C": "$\\mathbf{b}-\\mathbf{a}$", "D": "$\\tfrac12(\\mathbf{a}+\\mathbf{b})$"}'::jsonb, 'A', 'Travel from $A$ to $C$ by way of $B$: $\vec{AC}=\vec{AB}+\vec{BC}$. In a parallelogram $\vec{BC}=\vec{AD}=\mathbf{b}$, so $$\vec{AC}=\mathbf{a}+\mathbf{b}.$$', '{"B": "that is $\\vec{DB}$, the other diagonal taken from $D$", "C": "that is $\\vec{BD}$ — the other diagonal, in the other direction", "D": "that is $\\vec{AM}$, the vector to the CENTRE of the parallelogram"}'::jsonb),
  ('combinations--r3', 'combinations', 'eysh', 3, 'A committee of $4$ is chosen from $6$ men and $5$ women. How many committees contain at least $3$ women?', '{"A": "$65$", "B": "$60$", "C": "$70$", "D": "$5$"}'::jsonb, 'A', '''''At least $3$ women'''' splits into exactly $3$ and exactly $4$: $$\binom53\binom61+\binom54\binom60=10(6)+5(1)=60+5=65.$$', '{"B": "counted only the committees with exactly $3$ women", "C": "added $10+60$, double-counting the $\\binom53$ term", "D": "counted only the all-women committees"}'::jsonb),
  ('permutations--r1', 'permutations', 'eysh', 1, 'In how many different orders can the three letters $C$, $A$, $T$ be arranged?', '{"A": "$6$", "B": "$3$", "C": "$9$", "D": "$27$"}'::jsonb, 'A', 'There are $3$ choices for the first letter, $2$ for the second and $1$ for the last: $$3!=3\times2\times1=6.$$', '{"B": "gave the number of letters rather than the number of orders", "C": "computed $3^2$", "D": "computed $3^3$, which would allow letters to repeat"}'::jsonb),
  ('inclusion-exclusion--r1', 'inclusion-exclusion', 'eysh', 1, '$|A|=10$, $|B|=8$ and $|A\cap B|=3$. Find $|A\cup B|$.', '{"A": "$15$", "B": "$18$", "C": "$21$", "D": "$5$"}'::jsonb, 'A', '$$|A\cup B|=|A|+|B|-|A\cap B|=10+8-3=15.$$ The overlap is subtracted because adding both sets counts it twice.', '{"B": "forgot to remove the double-counted overlap", "C": "added the overlap instead of subtracting it", "D": "subtracted the wrong quantity"}'::jsonb),
  ('inclusion-exclusion--r3', 'inclusion-exclusion', 'eysh', 3, 'In a class of $30$, $18$ study French and $15$ study German. $5$ study neither. How many study both?', '{"A": "$8$", "B": "$3$", "C": "$12$", "D": "$5$"}'::jsonb, 'A', 'Those studying at least one subject number $30-5=25$. Then $$|F\cup G|=|F|+|G|-|F\cap G|\ \Longrightarrow\ 25=18+15-|F\cap G|,$$ so $|F\cap G|=33-25=8$.', '{"B": "used $30$ instead of $25$, forgetting the $5$ who study neither", "C": "gave the number studying French only, $18-... $ — not the overlap", "D": "repeated the ''''neither'''' figure"}'::jsonb),
  ('decimal-arithmetic--r3', 'decimal-arithmetic', 'eysh', 3, 'A number rounds to $4.7$ when given to $2$ significant figures. What is the smallest it could be?', '{"A": "$4.65$", "B": "$4.6$", "C": "$4.651$", "D": "$4.75$"}'::jsonb, 'A', 'Two significant figures here means rounding to the nearest tenth. Values from $4.65$ up to (but not including) $4.75$ all round to $4.7$, and $4.65$ itself rounds up by convention. So the smallest is $4.65$.', '{"B": "$4.6$ rounds to $4.6$, not $4.7$", "C": "there is no smallest value above $4.65$ — $4.65$ is included", "D": "that is the upper bound, and it rounds to $4.8$"}'::jsonb),
  ('complex-conjugate-division--r1', 'complex-conjugate-division', 'eysh', 1, 'Find the complex conjugate of $3-2i$.', '{"A": "$3+2i$", "B": "$-3+2i$", "C": "$-3-2i$", "D": "$2-3i$"}'::jsonb, 'A', 'The conjugate flips the sign of the imaginary part only: $\overline{3-2i}=3+2i$. A useful check is that the product $(3-2i)(3+2i)=9+4=13$ is real.', '{"B": "negated both parts", "C": "negated the real part only", "D": "swapped the real and imaginary parts"}'::jsonb),
  ('complex-conjugate-division--r3', 'complex-conjugate-division', 'eysh', 3, 'Simplify $\dfrac{2+3i}{1-i}$.', '{"A": "$\\dfrac{-1+5i}{2}$", "B": "$-1+5i$", "C": "$\\dfrac{5-i}{2}$", "D": "$\\dfrac{2+3i}{2}$"}'::jsonb, 'A', 'Multiply top and bottom by the conjugate of the denominator: $$\frac{2+3i}{1-i}\cdot\frac{1+i}{1+i}=\frac{2+2i+3i+3i^2}{1-i^2}=\frac{-1+5i}{2}.$$ Remember $i^2=-1$, so the numerator''s $3i^2$ becomes $-3$.', '{"B": "forgot to divide by the denominator $(1-i)(1+i)=2$", "C": "multiplied by $1-i$ instead of by the conjugate $1+i$", "D": "divided by $2$ without multiplying out the numerator"}'::jsonb),
  ('complex-roots-of-quadratics--r1', 'complex-roots-of-quadratics', 'eysh', 1, 'Solve $x^2+9=0$.', '{"A": "$x=\\pm 3i$", "B": "$x=\\pm 3$", "C": "$x=\\pm 9i$", "D": "no solution"}'::jsonb, 'A', '$x^2=-9$, and $\sqrt{-9}=3i$ since $(3i)^2=9i^2=-9$. So $x=\pm 3i$.', '{"B": "solved $x^2=9$, dropping the minus sign", "C": "forgot to take the square root of $9$", "D": "true over the reals, but the question allows complex solutions"}'::jsonb),
  ('complex-roots-of-quadratics--r3', 'complex-roots-of-quadratics', 'eysh', 3, '$x^2-4x+13=0$. Find the roots.', '{"A": "$x=2\\pm 3i$", "B": "$x=-2\\pm 3i$", "C": "$x=2\\pm 9i$", "D": "$x=4\\pm 3i$"}'::jsonb, 'A', 'The discriminant is $16-52=-36$, so $$x=\frac{4\pm\sqrt{-36}}{2}=\frac{4\pm 6i}{2}=2\pm 3i.$$ The two roots are conjugates, as they always are for a real quadratic.', '{"B": "used $-b=-4$ instead of $+4$", "C": "took $\\sqrt{-36}$ as $9i$ and never divided by $2$", "D": "forgot to divide the whole numerator by $2$"}'::jsonb),
  ('permutations-with-restrictions--r1', 'permutations-with-restrictions', 'eysh', 1, 'How many arrangements of the letters $A$, $B$, $C$ begin with $A$?', '{"A": "$2$", "B": "$6$", "C": "$3$", "D": "$1$"}'::jsonb, 'A', 'Fix $A$ in the first place. The remaining two letters can be arranged in $2!=2$ ways: $ABC$ and $ACB$.', '{"B": "counted every arrangement, ignoring the restriction", "C": "used the number of letters", "D": "assumed fixing one letter fixes them all"}'::jsonb),
  ('cayley-hamilton--r1', 'cayley-hamilton', 'eysh', 1, 'A $2\times2$ matrix $A$ has trace $5$ and determinant $6$. Write its characteristic equation.', '{"A": "$A^2-5A+6I=O$", "B": "$A^2+5A+6I=O$", "C": "$A^2-6A+5I=O$", "D": "$A^2-5A-6I=O$"}'::jsonb, 'A', 'Cayley–Hamilton says a matrix satisfies its own characteristic equation, which for $2\times2$ is $$A^2-(\operatorname{tr}A)A+(\det A)I=O.$$ With trace $5$ and determinant $6$ that is $A^2-5A+6I=O$.', '{"B": "the trace term is subtracted, not added", "C": "swapped the trace and the determinant", "D": "the determinant term is added, not subtracted"}'::jsonb),
  ('determinant-2x2--r1', 'determinant-2x2', 'eysh', 1, 'Find $\begin{vmatrix}3&4\\1&2\end{vmatrix}$.', '{"A": "$2$", "B": "$10$", "C": "$-2$", "D": "$14$"}'::jsonb, 'A', '$$\begin{vmatrix}a&b\\c&d\end{vmatrix}=ad-bc=3(2)-4(1)=6-4=2.$$', '{"B": "added the two products instead of subtracting", "C": "subtracted the other way round, $bc-ad$", "D": "multiplied along the wrong pairs"}'::jsonb),
  ('determinant-2x2--r3', 'determinant-2x2', 'eysh', 3, 'For which values of $k$ is $\begin{pmatrix}k&2\\8&k\end{pmatrix}$ singular?', '{"A": "$k=4$ or $k=-4$", "B": "$k=4$ only", "C": "$k=16$ or $k=-16$", "D": "$k=2$ or $k=-2$"}'::jsonb, 'A', 'A matrix is singular exactly when its determinant is zero: $$k(k)-2(8)=k^2-16=0\ \Longrightarrow\ k=\pm 4.$$', '{"B": "took only the positive square root", "C": "forgot to take the square root of $16$", "D": "used the entry $2$ rather than solving $k^2=16$"}'::jsonb),
  ('matrix-dimensions--r3', 'matrix-dimensions', 'eysh', 3, '$A$ is $3\times4$, $B$ is $4\times2$ and $C$ is $2\times3$. What are the dimensions of $ABC$?', '{"A": "$3\\times3$", "B": "$3\\times2$", "C": "$2\\times2$", "D": "the product is not defined"}'::jsonb, 'A', 'Inner dimensions must match and the outer ones survive. $AB$ is $3\times4$ times $4\times2$, giving $3\times2$. Then $(AB)C$ is $3\times2$ times $2\times3$, giving $3\times3$.', '{"B": "stopped after $AB$ and never multiplied by $C$", "C": "took the dimensions of $C$ instead of the product", "D": "the inner dimensions do match at each step, so the product exists"}'::jsonb),
  ('vector-magnitude--r1', 'vector-magnitude', 'eysh', 1, 'Find $|\mathbf{v}|$ for $\mathbf{v}=(3,-4)$.', '{"A": "$5$", "B": "$7$", "C": "$25$", "D": "$1$"}'::jsonb, 'A', '$$|\mathbf{v}|=\sqrt{3^2+(-4)^2}=\sqrt{9+16}=\sqrt{25}=5.$$', '{"B": "added the components'' sizes instead of using Pythagoras", "C": "stopped at $|\\mathbf{v}|^2$ and forgot the square root", "D": "gave the magnitude of the unit vector"}'::jsonb),
  ('vector-magnitude--r3', 'vector-magnitude', 'eysh', 3, 'Find the unit vector in the direction of $\mathbf{v}=(1,2,-2)$.', '{"A": "$\\left(\\tfrac13,\\tfrac23,-\\tfrac23\\right)$", "B": "$\\left(\\tfrac19,\\tfrac29,-\\tfrac29\\right)$", "C": "$\\left(\\tfrac13,\\tfrac23,\\tfrac23\\right)$", "D": "$\\left(\\tfrac{1}{\\sqrt5},\\tfrac{2}{\\sqrt5},-\\tfrac{2}{\\sqrt5}\\right)$"}'::jsonb, 'A', 'First the magnitude: $|\mathbf{v}|=\sqrt{1+4+4}=\sqrt9=3$. Divide each component by it: $$\hat{\mathbf{v}}=\left(\tfrac13,\tfrac23,-\tfrac23\right).$$ Check: $\tfrac19+\tfrac49+\tfrac49=1$. ✓', '{"B": "divided by $|\\mathbf{v}|^2=9$ instead of by $|\\mathbf{v}|=3$", "C": "lost the sign on the third component", "D": "used $\\sqrt5$, having summed only the first two squares"}'::jsonb),
  ('vector-section-formula--r1', 'vector-section-formula', 'eysh', 1, '$A$ is the origin and $B=(6,3)$. Find the point $P$ dividing $AB$ in the ratio $1:2$.', '{"A": "$(2,1)$", "B": "$(4,2)$", "C": "$(3,1.5)$", "D": "$(1,2)$"}'::jsonb, 'A', 'A ratio $1:2$ puts $P$ one third of the way from $A$ to $B$: $$P=\tfrac13(6,3)=(2,1).$$', '{"B": "went two thirds of the way — that is the ratio $2:1$", "C": "went halfway, as though the ratio were $1:1$", "D": "swapped the coordinates"}'::jsonb),
  ('cosine-rule--r1', 'cosine-rule', 'eysh', 1, 'In triangle $ABC$, $a=5$, $b=7$ and $C=60^\circ$. Find $c$.', '{"A": "$\\sqrt{39}$", "B": "$\\sqrt{74}$", "C": "$\\sqrt{109}$", "D": "$39$"}'::jsonb, 'A', '$$c^2=a^2+b^2-2ab\cos C=25+49-2(5)(7)\left(\tfrac12\right)=74-35=39,$$ so $c=\sqrt{39}$.', '{"B": "used Pythagoras, which needs a right angle — this triangle has none", "C": "added the $2ab\\cos C$ term instead of subtracting it", "D": "stopped at $c^2$ and forgot the square root"}'::jsonb),
  ('cosine-rule--r3', 'cosine-rule', 'eysh', 3, 'A triangle has sides $5$, $6$ and $7$. Find the cosine of the angle opposite the side of length $7$.', '{"A": "$\\dfrac15$", "B": "$-\\dfrac15$", "C": "$\\dfrac25$", "D": "$\\dfrac{6}{35}$"}'::jsonb, 'A', 'Rearrange the cosine rule for the angle opposite $c=7$: $$\cos C=\frac{a^2+b^2-c^2}{2ab}=\frac{25+36-49}{2(5)(6)}=\frac{12}{60}=\frac15.$$', '{"B": "wrote $c^2-a^2-b^2$ on top, reversing the sign", "C": "divided by $ab=30$ instead of $2ab=60$", "D": "used the sides $5$ and $7$ in the denominator; they must be the two sides ENCLOSING the angle"}'::jsonb),
  ('exact-trig-values--r3', 'exact-trig-values', 'eysh', 3, 'Find the exact value of $\tan 240^\circ-\sin 300^\circ$.', '{"A": "$\\dfrac{3\\sqrt3}{2}$", "B": "$\\dfrac{\\sqrt3}{2}$", "C": "$\\sqrt3$", "D": "$-\\dfrac{\\sqrt3}{2}$"}'::jsonb, 'A', '$240^\circ$ is in the third quadrant where tangent is positive, and its reference angle is $60^\circ$, so $\tan 240^\circ=\sqrt3$. $300^\circ$ is in the fourth quadrant where sine is negative, with the same reference angle, so $\sin 300^\circ=-\tfrac{\sqrt3}{2}$. Then $$\sqrt3-\left(-\tfrac{\sqrt3}{2}\right)=\sqrt3+\tfrac{\sqrt3}{2}=\tfrac{3\sqrt3}{2}.$$', '{"B": "took $\\tan 240^\\circ$ as $\\tfrac{\\sqrt3}{2}$ — that is a sine value, not a tangent", "C": "treated $\\sin 300^\\circ$ as positive, so the two terms cancelled to $\\sqrt3$", "D": "subtracted the wrong way round and lost the tangent term"}'::jsonb),
  ('sine-rule--r1', 'sine-rule', 'eysh', 1, 'In triangle $ABC$, $A=30^\circ$, $B=90^\circ$ and $a=5$. Find $b$.', '{"A": "$10$", "B": "$\\dfrac52$", "C": "$20$", "D": "$5\\sqrt3$"}'::jsonb, 'A', '$$\frac{b}{\sin B}=\frac{a}{\sin A}\ \Longrightarrow\ b=\frac{a\sin B}{\sin A}=\frac{5\times 1}{\tfrac12}=10.$$', '{"B": "inverted the ratio, computing $a\\sin A/\\sin B$", "C": "doubled twice", "D": "used the third angle $60^\\circ$ instead of $B=90^\\circ$"}'::jsonb),
  ('sine-rule--r3', 'sine-rule', 'eysh', 3, 'In triangle $ABC$, $a=6$, $b=8$ and $A=30^\circ$. How many triangles satisfy this data?', '{"A": "two", "B": "one", "C": "none", "D": "infinitely many"}'::jsonb, 'A', 'This is the ambiguous (SSA) case. The sine rule gives $$\sin B=\frac{b\sin A}{a}=\frac{8\times\tfrac12}{6}=\frac23,$$ which is less than $1$, so $B$ exists. Because $a<b$ AND $a>b\sin A$ (that is, $6>4$), the side $a$ is long enough to reach the base in two places: both the acute $B$ and its obtuse partner $180^\circ-B$ give a valid triangle.', '{"B": "took only the acute value of $B$ and missed the obtuse one", "C": "$\\sin B=\\tfrac23\\le 1$, so a triangle certainly exists", "D": "the data fixes the triangle up to two possibilities, not infinitely many"}'::jsonb),
  ('trig-equations--r1', 'trig-equations', 'eysh', 1, 'Solve $\sin x=\tfrac12$ for $0\le x<2\pi$.', '{"A": "$x=\\dfrac{\\pi}{6}$ or $x=\\dfrac{5\\pi}{6}$", "B": "$x=\\dfrac{\\pi}{6}$ only", "C": "$x=\\dfrac{\\pi}{6}$ or $x=\\dfrac{7\\pi}{6}$", "D": "$x=\\dfrac{\\pi}{3}$ or $x=\\dfrac{2\\pi}{3}$"}'::jsonb, 'A', '$\sin\tfrac{\pi}{6}=\tfrac12$, and sine is also positive in the second quadrant, where the solution is $\pi-\tfrac{\pi}{6}=\tfrac{5\pi}{6}$. Both lie in $[0,2\pi)$.', '{"B": "stopped at the first quadrant; sine is positive in the second as well", "C": "used $\\pi+\\tfrac{\\pi}{6}$, which is where sine is NEGATIVE", "D": "solved $\\sin x=\\tfrac{\\sqrt3}{2}$ instead"}'::jsonb),
  ('trig-equations--r3', 'trig-equations', 'eysh', 3, 'Solve $2\cos^2x-\cos x-1=0$ for $0\le x<2\pi$.', '{"A": "$x=0,\\ \\dfrac{2\\pi}{3},\\ \\dfrac{4\\pi}{3}$", "B": "$x=\\dfrac{2\\pi}{3},\\ \\dfrac{4\\pi}{3}$", "C": "$x=0,\\ \\dfrac{\\pi}{3},\\ \\dfrac{5\\pi}{3}$", "D": "$x=\\pi,\\ \\dfrac{2\\pi}{3},\\ \\dfrac{4\\pi}{3}$"}'::jsonb, 'A', 'Treat it as a quadratic in $c=\cos x$: $$2c^2-c-1=(c-1)(2c+1)=0,$$ so $\cos x=1$ or $\cos x=-\tfrac12$. $\cos x=1$ gives $x=0$; $\cos x=-\tfrac12$ gives $x=\tfrac{2\pi}{3}$ and $x=\tfrac{4\pi}{3}$.', '{"B": "solved $\\cos x=-\\tfrac12$ but dropped the root $\\cos x=1$", "C": "used $\\cos x=\\tfrac12$ instead of $-\\tfrac12$", "D": "took $\\cos x=1$ to give $x=\\pi$; $\\cos\\pi=-1$, not $1$"}'::jsonb),
  ('trig-simplification--r1', 'trig-simplification', 'eysh', 1, 'Simplify $\sin^2x+\cos^2x$.', '{"A": "$1$", "B": "$0$", "C": "$\\sin 2x$", "D": "$2$"}'::jsonb, 'A', 'This is the Pythagorean identity: $\sin^2x+\cos^2x=1$ for every $x$.', '{"B": "that is $\\sin^2x-\\cos^2x$ only when $x=\\tfrac{\\pi}{4}$, and it is not an identity", "C": "$\\sin 2x=2\\sin x\\cos x$ — a product, not a sum of squares", "D": "the identity gives $1$, not $2$"}'::jsonb),
  ('trig-simplification--r2', 'trig-simplification', 'eysh', 2, 'Simplify $\dfrac{1-\cos^2x}{\sin x}$, where $\sin x\ne 0$.', '{"A": "$\\sin x$", "B": "$\\cos x$", "C": "$\\tan x$", "D": "$\\dfrac{1}{\\sin x}$"}'::jsonb, 'A', 'By the Pythagorean identity $1-\cos^2x=\sin^2x$, so $$\frac{1-\cos^2x}{\sin x}=\frac{\sin^2x}{\sin x}=\sin x.$$', '{"B": "used $1-\\cos^2x=\\cos^2 x$", "C": "cancelled as though the numerator were $\\sin x\\cos x$", "D": "inverted the fraction after cancelling"}'::jsonb),
  ('solid-of-revolution-geometric--r1', 'solid-of-revolution-geometric', 'eysh', 1, 'A rectangle is rotated a full turn about one of its sides. What solid is generated?', '{"A": "a cylinder", "B": "a cone", "C": "a sphere", "D": "a prism"}'::jsonb, 'A', 'Every point of the rectangle sweeps a circle centred on the axis. The side along the axis stays fixed and the opposite side sweeps out a circle of constant radius, so the surface is a cylinder of radius equal to the other side.', '{"B": "a cone comes from rotating a right TRIANGLE about a leg", "C": "a sphere comes from rotating a semicircle about its diameter", "D": "a prism has flat sides; rotation always produces circular cross-sections"}'::jsonb),
  ('solid-of-revolution-geometric--r3', 'solid-of-revolution-geometric', 'eysh', 3, 'A right-angled triangle with legs $3$ and $4$ is rotated a full turn about the leg of length $3$. Find the volume of the solid.', '{"A": "$16\\pi$", "B": "$12\\pi$", "C": "$48\\pi$", "D": "$\\dfrac{25\\pi}{3}$"}'::jsonb, 'A', 'Rotating about the leg of length $3$ makes that leg the AXIS, so it is the height; the other leg, $4$, sweeps out the base circle and is therefore the radius. $$V=\tfrac13\pi r^2h=\tfrac13\pi(4)^2(3)=16\pi.$$', '{"B": "swapped radius and height — the leg on the axis is the height", "C": "used the cylinder formula, dropping the factor $\\tfrac13$", "D": "used the hypotenuse $5$ as the radius"}'::jsonb),
  ('integer-powers--r2', 'integer-powers', 'eysh', 2, 'Evaluate $2^{-3}$.', '{"A": "$\\dfrac18$", "B": "$-8$", "C": "$-6$", "D": "$8$"}'::jsonb, 'A', 'A negative exponent means a reciprocal, not a negative value: $$2^{-3}=\frac{1}{2^3}=\frac18.$$', '{"B": "made the RESULT negative; the minus sign belongs to the exponent", "C": "multiplied $2\\times(-3)$", "D": "ignored the minus sign entirely"}'::jsonb),
  ('integer-powers--r3', 'integer-powers', 'eysh', 3, 'Simplify $\dfrac{2^{-2}\cdot 3^{3}}{2^{-4}\cdot 3}$.', '{"A": "$36$", "B": "$4$", "C": "$9$", "D": "$\\dfrac{1}{36}$"}'::jsonb, 'A', 'Subtract exponents on matching bases: $$2^{-2-(-4)}\cdot 3^{3-1}=2^{2}\cdot 3^{2}=4\times 9=36.$$ Note $-2-(-4)=+2$ — the double negative raises the power.', '{"B": "handled the powers of $2$ and dropped the powers of $3$", "C": "handled the powers of $3$ and dropped the powers of $2$", "D": "subtracted the exponents the wrong way round on both bases"}'::jsonb),
  ('percent-and-proportion--r2', 'percent-and-proportion', 'eysh', 2, 'Find $15\%$ of $240$.', '{"A": "$36$", "B": "$16$", "C": "$3.6$", "D": "$360$"}'::jsonb, 'A', '$$15\%\text{ of }240=\frac{15}{100}\times 240=36.$$', '{"B": "divided $240$ by $15$ instead of taking $15\\%$ of it", "C": "divided by $1000$ rather than $100$", "D": "multiplied by $15$ and divided by $10$"}'::jsonb),
  ('percent-and-proportion--r3', 'percent-and-proportion', 'eysh', 3, 'A price rises by $20\%$ and then falls by $20\%$. What is the net change?', '{"A": "a $4\\%$ decrease", "B": "no change", "C": "a $4\\%$ increase", "D": "a $40\\%$ increase"}'::jsonb, 'A', 'Multiply the two factors: $$1.20\times 0.80=0.96,$$ so the final price is $96\%$ of the original — a $4\%$ decrease. The second percentage is taken of the LARGER amount, so the fall outweighs the rise.', '{"B": "assumed the two $20\\%$ changes cancel; they are percentages of different amounts", "C": "got the size right but the direction wrong", "D": "added the percentages instead of compounding them"}'::jsonb),
  ('radicals-simplification--r3', 'radicals-simplification', 'eysh', 3, 'Simplify $\sqrt{50}-\sqrt{18}+\sqrt{8}$.', '{"A": "$4\\sqrt2$", "B": "$6\\sqrt2$", "C": "$\\sqrt{40}$", "D": "$10\\sqrt2$"}'::jsonb, 'A', 'Reduce each surd to a multiple of $\sqrt2$: $$\sqrt{50}=5\sqrt2,\quad\sqrt{18}=3\sqrt2,\quad\sqrt8=2\sqrt2.$$ Then $5\sqrt2-3\sqrt2+2\sqrt2=4\sqrt2$.', '{"B": "added all three instead of subtracting the middle term", "C": "added the numbers under the roots, $50-18+8$; surds do not combine that way", "D": "used $\\sqrt{50}=5\\sqrt2$ but $\\sqrt{18}=\\sqrt2$ and $\\sqrt8=4\\sqrt2$"}'::jsonb),
  ('stars-and-bars--r1', 'stars-and-bars', 'eysh', 1, 'How many solutions in non-negative integers does $x+y=4$ have?', '{"A": "$5$", "B": "$4$", "C": "$3$", "D": "$10$"}'::jsonb, 'A', 'Choose $x$ freely from $0$ to $4$; $y$ is then forced. That is $5$ solutions: $(0,4),(1,3),(2,2),(3,1),(4,0)$.', '{"B": "forgot that $x=0$ is allowed", "C": "counted only the solutions with both parts positive and distinct", "D": "used $\\binom{5}{2}$, the formula for THREE unknowns"}'::jsonb),
  ('stars-and-bars--r3', 'stars-and-bars', 'eysh', 3, 'How many solutions in non-negative integers does $x+y+z=8$ have?', '{"A": "$45$", "B": "$36$", "C": "$21$", "D": "$28$"}'::jsonb, 'A', 'Place $8$ stars and $2$ bars in a row; each arrangement is one solution. There are $8+2=10$ positions and the bars occupy $2$ of them: $$\binom{8+3-1}{3-1}=\binom{10}{2}=45.$$', '{"B": "used $\\binom{9}{2}$ — one star short", "C": "used $\\binom{7}{2}$, as though the parts had to be positive", "D": "used $\\binom{8}{2}$, forgetting to add the bars to the total"}'::jsonb),
  ('trig-sum-difference--r1', 'trig-sum-difference', 'eysh', 1, 'Which expression equals $\cos(A+B)$?', '{"A": "$\\cos A\\cos B-\\sin A\\sin B$", "B": "$\\cos A\\cos B+\\sin A\\sin B$", "C": "$\\sin A\\cos B+\\cos A\\sin B$", "D": "$\\cos A+\\cos B$"}'::jsonb, 'A', '$$\cos(A+B)=\cos A\cos B-\sin A\sin B.$$ The sign flips relative to the $+$ in the bracket — that is the part worth memorising.', '{"B": "that is $\\cos(A-B)$", "C": "that is $\\sin(A+B)$", "D": "cosine is not additive; $\\cos(A+B)\\ne\\cos A+\\cos B$"}'::jsonb),
  ('trig-sum-difference--r2', 'trig-sum-difference', 'eysh', 2, 'Find the exact value of $\sin 75^\circ$.', '{"A": "$\\dfrac{\\sqrt6+\\sqrt2}{4}$", "B": "$\\dfrac{\\sqrt6-\\sqrt2}{4}$", "C": "$\\dfrac{\\sqrt2+1}{2}$", "D": "$\\dfrac{\\sqrt3+1}{2}$"}'::jsonb, 'A', 'Write $75^\circ=45^\circ+30^\circ$ and expand: $$\sin 75^\circ=\sin45\cos30+\cos45\sin30=\frac{\sqrt2}{2}\cdot\frac{\sqrt3}{2}+\frac{\sqrt2}{2}\cdot\frac12=\frac{\sqrt6+\sqrt2}{4}.$$', '{"B": "that is $\\sin 15^\\circ$ — the difference $45^\\circ-30^\\circ$", "C": "added $\\sin45$ and $\\sin30$ directly", "D": "used $\\cos30+\\sin30$ without the $\\tfrac{\\sqrt2}{2}$ factors"}'::jsonb),
  ('geometric-sequence--r1', 'geometric-sequence', 'eysh', 1, 'A geometric sequence has first term $3$ and common ratio $2$. Find the fourth term.', '{"A": "$24$", "B": "$12$", "C": "$48$", "D": "$9$"}'::jsonb, 'A', '$$u_n=ar^{n-1}\ \Longrightarrow\ u_4=3\cdot 2^{3}=3\times 8=24.$$', '{"B": "used $r^{2}$ — off by one in the exponent", "C": "used $r^{4}$ instead of $r^{n-1}=r^{3}$", "D": "added the ratio each time, treating it as an arithmetic sequence"}'::jsonb),
  ('real-number-sets--r3', 'real-number-sets', 'eysh', 3, 'Which of these numbers is irrational?', '{"A": "$\\sqrt8$", "B": "$\\sqrt9$", "C": "$\\dfrac{22}{7}$", "D": "$0.25$"}'::jsonb, 'A', '$\sqrt9=3$ and $\tfrac{22}{7}$ and $0.25=\tfrac14$ are all ratios of integers, so all three are rational. $\sqrt8=2\sqrt2$, and $\sqrt2$ cannot be written as such a ratio, so $\sqrt8$ is irrational.', '{"B": "$\\sqrt9=3$ exactly — a square root is only irrational when the number is not a perfect square", "C": "$\\tfrac{22}{7}$ is a common approximation to $\\pi$, but it is itself a ratio of integers", "D": "$0.25$ terminates, so it equals $\\tfrac14$"}'::jsonb),
  ('repeating-decimal-to-fraction--r3', 'repeating-decimal-to-fraction', 'eysh', 3, 'Write $0.4\overline{27}$ (that is, $0.4272727\ldots$) as a fraction in lowest terms.', '{"A": "$\\dfrac{47}{110}$", "B": "$\\dfrac{423}{999}$", "C": "$\\dfrac{427}{990}$", "D": "$\\dfrac{47}{99}$"}'::jsonb, 'A', 'Let $x=0.4272727\ldots$. Shift past the non-repeating digit and past one full period: $$10x=4.272727\ldots,\qquad 1000x=427.272727\ldots$$ Subtract: $990x=423$, so $$x=\frac{423}{990}=\frac{47}{110}.$$', '{"B": "used $999$, which is the denominator only when ALL digits repeat", "C": "used $427$ on top, forgetting to subtract the $4$ from the shifted copy", "D": "used $99$, ignoring the non-repeating digit $4$"}'::jsonb),
  ('arithmetic-series--r3', 'arithmetic-series', 'eysh', 3, 'Find the sum of all multiples of $7$ between $100$ and $300$.', '{"A": "$5586$", "B": "$5481$", "C": "$5985$", "D": "$2793$"}'::jsonb, 'A', 'The first multiple of $7$ above $100$ is $105=7(15)$ and the last below $300$ is $294=7(42)$, so there are $42-15+1=28$ terms. Then $$S=\frac{n(a+l)}{2}=\frac{28(105+294)}{2}=14\times 399=5586.$$', '{"B": "used $27$ terms — the classic off-by-one from $42-15$", "C": "included $301$ as a term", "D": "forgot to halve, or halved twice"}'::jsonb),
  ('exponent-rules--r3', 'exponent-rules', 'eysh', 3, 'Simplify $\dfrac{\left(x^{3}y^{-2}\right)^{2}}{x^{-1}y^{3}}$.', '{"A": "$\\dfrac{x^{7}}{y^{7}}$", "B": "$x^{7}y^{7}$", "C": "$\\dfrac{x^{5}}{y^{7}}$", "D": "$\\dfrac{x^{7}}{y}$"}'::jsonb, 'A', 'Apply the power to each factor first: $(x^3y^{-2})^2=x^6y^{-4}$. Then subtract the denominator''s exponents: $$x^{6-(-1)}y^{-4-3}=x^{7}y^{-7}=\frac{x^{7}}{y^{7}}.$$', '{"B": "treated $y^{-7}$ as $y^{7}$", "C": "subtracted the $x$ exponents as $6-1$ instead of $6-(-1)$", "D": "subtracted only the $3$ from the $y$ exponent, forgetting the $-4$"}'::jsonb),
  ('logarithm-definition--r1', 'logarithm-definition', 'eysh', 1, 'Evaluate $\log_2 8$.', '{"A": "$3$", "B": "$4$", "C": "$2$", "D": "$\\dfrac13$"}'::jsonb, 'A', '$\log_2 8$ asks: to what power must $2$ be raised to give $8$? Since $2^3=8$, the answer is $3$.', '{"B": "answered $\\log_2 16$", "C": "gave the base rather than the exponent", "D": "inverted the answer"}'::jsonb),
  ('logarithm-definition--r3', 'logarithm-definition', 'eysh', 3, 'If $\log_a 8=\tfrac32$, find $a$.', '{"A": "$4$", "B": "$2$", "C": "$16$", "D": "$12$"}'::jsonb, 'A', 'Rewrite in exponential form: $a^{3/2}=8$. Raise both sides to the power $\tfrac23$: $$a=8^{2/3}=\left(\sqrt[3]{8}\right)^{2}=2^{2}=4.$$', '{"B": "gave $\\sqrt[3]{8}$ without squaring it", "C": "multiplied $8$ by $2$ instead of raising to the power $\\tfrac23$", "D": "computed $8\\times\\tfrac32$"}'::jsonb),
  ('logarithmic-equations--r1', 'logarithmic-equations', 'eysh', 1, 'Solve $\log_3 x=2$.', '{"A": "$x=9$", "B": "$x=6$", "C": "$x=8$", "D": "$x=\\dfrac32$"}'::jsonb, 'A', 'Convert to exponential form: $x=3^2=9$.', '{"B": "multiplied the base by the exponent", "C": "computed $3^2-1$", "D": "divided the base by the exponent"}'::jsonb),
  ('logarithmic-equations--r3', 'logarithmic-equations', 'eysh', 3, 'Solve $\log x+\log(x-3)=1$ (logarithms base $10$).', '{"A": "$x=5$", "B": "$x=5$ or $x=-2$", "C": "$x=-2$", "D": "$x=10$"}'::jsonb, 'A', 'Combine the logarithms: $\log\bigl(x(x-3)\bigr)=1$, so $x(x-3)=10$ and $$x^2-3x-10=0\ \Longrightarrow\ (x-5)(x+2)=0.$$ Now check the domain: a logarithm needs a positive argument. $x=-2$ makes $\log x$ undefined, so it is rejected. Only $x=5$ survives.', '{"B": "solved the quadratic but never checked that both logarithms are defined", "C": "kept the rejected root and discarded the valid one", "D": "set $x-3=10$, applying the $1$ to only one logarithm"}'::jsonb),
  ('logarithmic-inequalities--r3', 'logarithmic-inequalities', 'eysh', 3, 'Solve $\log_2(x-1)<3$.', '{"A": "$1<x<9$", "B": "$x<9$", "C": "$x>9$", "D": "$0<x<8$"}'::jsonb, 'A', 'The logarithm is only defined when $x-1>0$, so $x>1$ from the start. Since base $2$ is greater than $1$, the function increases and the inequality keeps its direction: $$x-1<2^3=8\ \Longrightarrow\ x<9.$$ Combining, $1<x<9$.', '{"B": "solved the inequality but ignored the domain restriction $x>1$", "C": "reversed the inequality, which only happens for a base below $1$", "D": "forgot to add the $1$ back after solving for $x-1$"}'::jsonb),
  ('rational-exponents--r3', 'rational-exponents', 'eysh', 3, 'Evaluate $27^{-2/3}$.', '{"A": "$\\dfrac19$", "B": "$9$", "C": "$-9$", "D": "$\\dfrac{1}{729}$"}'::jsonb, 'A', 'The denominator of the exponent is the root and the numerator is the power; the minus sign inverts: $$27^{-2/3}=\frac{1}{\left(\sqrt[3]{27}\right)^{2}}=\frac{1}{3^{2}}=\frac19.$$', '{"B": "ignored the minus sign", "C": "made the result negative instead of taking a reciprocal", "D": "squared $27$ before taking the cube root, then inverted"}'::jsonb)
